			IP4 := ROR(IP4,8);
		END_FOR;
		d := CONCAT(d,'in-addr.arpa');
		state := 10;
	END_IF;
10: 
	IF ip_state = BYTE#3 THEN
		dl := LEN(d);
		char_count := 17 + dl;
		FOR i := 0 TO char_count DO
			S_BUF.BUFFER[i] := BYTE#00;
		END_FOR;
		tid := UINT_TO_BYTE(BYTE_TO_UINT(tid) + UINT#1);
		S_BUF.BUFFER[01] := tid; 
		S_BUF.BUFFER[02] := BYTE#16#01; 
		S_BUF.BUFFER[05] := BYTE#16#01; 
		i := dl + 12;
		char_count := 0;
		WHILE i > 12 DO
			CODE(STR:=d,POS:=i - 12);
			char:=CODE.CODE;
			IF char = BYTE#46 THEN
				S_BUF.BUFFER[i] := INT_TO_BYTE(char_count);
				char_count := 0;
			ELSE
				S_BUF.BUFFER[i] := char; 
				char_count := char_count + 1; 
			END_IF;
			i := i - 1;
		END_WHILE;
		S_BUF.BUFFER[i] := INT_TO_BYTE(char_count); 
		i := dl + 15; 
		S_BUF.BUFFER[i] := BYTE#12; 
		i := i + 2;
		S_BUF.BUFFER[i] := BYTE#01; 
		i := i + 1;
		IP_C.C_PORT := WORD#53; 
		IP_C.C_IP := IP4_DNS; 
		IP_C.C_MODE := BYTE#1; 
		IP_C.C_ENABLE := TRUE; 
		IP_C.TIME_RESET := TRUE; 
		IP_C.R_OBSERVE  := TRUE; 
		S_BUF.SIZE := INT_TO_UINT(i); 
		R_BUF.SIZE := UINT#0; 
		state := 30;
	END_IF;
30:
	IF IP_C.ERROR <> DWORD#00 THEN
		ERROR := IP_C.ERROR;
	ELSIF (S_BUF.SIZE = UINT#0) AND (tid = R_BUF.BUFFER[1]) AND (R_BUF.SIZE >= INT_TO_UINT(i+12)) THEN
		ERROR := BYTE_TO_DWORD(R_BUF.BUFFER[3] AND BYTE#2#0000_1111);
		IF ERROR = DWORD#00 THEN
			i := UINT_TO_INT(R_BUF.SIZE) - 2;
			WHILE R_BUF.BUFFER[i] > BYTE#0 DO
				IF i = 0 THEN EXIT; END_IF;
				i := i - 1;
			END_WHILE;
			i := i + 2;
			p1 := i + 1;
			WHILE i < UINT_TO_INT(R_BUF.SIZE) DO
				dl := _BYTE_TO_INT(R_BUF.BUFFER[i]);
				IF dl > 0 THEN
					R_BUF.BUFFER[i] := BYTE#46;
					i := i + dl + 1;
				ELSE
					BUFFER_TO_STRING(PT:=R_BUF.BUFFER,SIZE:=UINT#4096,START:=INT_TO_UINT(p1),STOP:=INT_TO_UINT(i-1));
					R_BUF.BUFFER:=BUFFER_TO_STRING.PT;
					DOMAIN:=BUFFER_TO_STRING.BUFFER_TO_STRING;
					EXIT;
				END_IF;
			END_WHILE;
			state := 0;
			DONE := TRUE;
		END_IF;
	END_IF;
	IF ERROR <> DWORD#0 THEN
		state := 0;
	END_IF;
	IF state = 0 THEN
		IP_C.R_OBSERVE := FALSE; 
		ip_state := BYTE#4; 
	END_IF;
