	FSTRING_TO_BYTE := OCT_TO_BYTE.OCT_TO_BYTE;
ELSE
    tmp := LEFT(IN,MIN(3,LEN(IN)));
    IF EQ_STRING(tmp,'16#') THEN
        HEX_TO_BYTE(HEX:=RIGHT(in, LEN(in) - 3));
	    FSTRING_TO_BYTE := HEX_TO_BYTE.HEX_TO_BYTE;
    ELSE
        CLEAN(IN:=in,CX:='0123456789');
	    FSTRING_TO_BYTE := STRING_TO_BYTE(CLEAN.CLEAN);
    END_IF;
END_IF;
END_FUNCTION_BLOCK

dy := 1970;
dm := 1;
dd := 1;
th := 0;
tm := 0;
ts := 0;
FSTRING_TO_DT := UDINT#0;
WHILE (LEN(fmt)>0) DO
	c := LEFT(fmt,1);
	IF EQ_STRING(c,ignore) THEN
		fmt := DELETE(fmt,1,1);
		IF LEN(sdt)>0 THEN sdt := DELETE(sdt,1,1); END_IF;
	ELSIF EQ_STRING(C,fchar) THEN
		IF LEN(fmt) >=2 THEN
		    c := MID(fmt,1,2);
		    fmt := DELETE(fmt,2,1);
        ELSE
		    c := '';
			fmt := '';
		END_IF;
		IF LEN(fmt) = 0 THEN
			tmp := sdt;
		ELSE
		    dm := dm;
            tmp1 := LEFT(fmt,1);
			end := FIND(sdt,tmp1)-1;
            IF end > 0 AND end <= LEN(sdt) THEN
			    tmp := LEFT(sdt, end);
            ELSE
			    tmp := '';
            END_IF;
			sdt := DELETE(sdt, end,1);
        END_IF;
        IS_NUM(str:=tmp);
        IF IS_NUM.IS_NUM THEN
		    tmp2 := STRING_TO_INT(tmp);
        ELSE
		    tmp2 := 0;
	    END_IF;
		IF EQ_STRING(c,'Y') THEN
			dy := tmp2;
			IF dy < 100 THEN dy := dy + 2000; END_IF;
		ELSIF EQ_STRING(c,'M') THEN
			dm := tmp2;
		ELSIF EQ_STRING(c,'N') THEN
		    dm := dm;
            FSTRING_TO_MONTH(MTH:=tmp,LANG:=0);
            dm := FSTRING_TO_MONTH.FSTRING_TO_MONTH;
		ELSIF EQ_STRING(c,'D') THEN
			dd := tmp2;
		ELSIF EQ_STRING(c,'h') THEN
			th := tmp2;
		ELSIF EQ_STRING(c,'m') THEN
			tm := tmp2;
		ELSIF EQ_STRING(c,'s') THEN
			ts := tmp2;
		END_IF;
	ELSE
        tmp1 := LEFT(sdt,1);
	    IF EQ_STRING(c,tmp1) THEN
		    fmt := DELETE(fmt,1,1);
		    sdt := DELETE(sdt,1,1);
	    ELSE
		    RETURN;
  	    END_IF;
	END_IF;
END_WHILE;
FSTRING_TO_DT := SET_DT(dy,dm,dd,th,tm,ts);
END_FUNCTION_BLOCK

tmp := LEFT(IN, 2);
IF EQ_STRING(tmp,'2#') THEN
    BIN_TO_DWORD(BIN:=RIGHT(in, LEN(in) - 2));
	FSTRING_TO_DWORD := BIN_TO_DWORD.BIN_TO_DWORD;
ELSIF EQ_STRING(tmp,'8#') THEN
    OCT_TO_DWORD(OCT:=RIGHT(in, LEN(in) - 2));
	FSTRING_TO_DWORD := OCT_TO_DWORD.OCT_TO_DWORD;
ELSE
    tmp := LEFT(IN, 3);
    IF EQ_STRING(tmp,'16#') THEN
        HEX_TO_DWORD(HEX:=RIGHT(in, LEN(in) - 3));
	    FSTRING_TO_DWORD := HEX_TO_DWORD.HEX_TO_DWORD;
    ELSE
        CLEAN(IN:=in,CX:='0123456789');
	    FSTRING_TO_DWORD := STRING_TO_DWORD(CLEAN.CLEAN);
    END_IF;
END_IF;
END_FUNCTION_BLOCK

SETUP_MONTHS(MONTHS:=MONTHS);
MONTHS:=SETUP_MONTHS.MONTHS;
SETUP_MONTHS3(MONTHS3:=MONTHS3);
MONTHS3:=SETUP_MONTHS3.MONTHS3;
SETUP_LANGUAGE(LANGUAGE:=LANGUAGE);
LANGUAGE:=SETUP_LANGUAGE.LANGUAGE;
IF LANG = 0 THEN lx := LANGUAGE.DEFAULT; ELSE lx := MIN(LANG, LANGUAGE.LMAX); END_IF;
LOWERCASE(str:=MTH);
CAPITALIZE(str:=LOWERCASE.lowercase);
MTH:=CAPITALIZE.CAPITALIZE;
FOR FSTRING_TO_MONTH := 1 TO 12 DO
	IF EQ_STRING(MTH,MONTHS[lx][FSTRING_TO_MONTH]) THEN RETURN; END_IF;
	IF EQ_STRING(MTH,MONTHS3[lx][FSTRING_TO_MONTH]) THEN RETURN; END_IF;
END_FOR;
IS_NUM(str:=MTH);
IF IS_NUM.IS_NUM THEN
	FSTRING_TO_MONTH := STRING_TO_INT(MTH);
ELSE
	FSTRING_TO_MONTH := 0;
END_IF;
END_FUNCTION_BLOCK

pos := FIND(WEEK, ',');
WHILE pos > 0 DO
    FSTRING_TO_WEEKDAY(WDAY:=MID(WEEK, pos - 1, 1),LANG:=LANG);
	FSTRING_TO_WEEK := FSTRING_TO_WEEK OR SHR_BYTE(BYTE#128, FSTRING_TO_WEEKDAY.FSTRING_TO_WEEKDAY);
	WEEK := RIGHT(WEEK, LEN(Week) - pos);
	pos := FIND(WEEK, ',');
END_WHILE;
FSTRING_TO_WEEKDAY(WDAY:=WEEK,LANG:=LANG);
FSTRING_TO_WEEK := (FSTRING_TO_WEEK OR SHR(BYTE#128, FSTRING_TO_WEEKDAY.FSTRING_TO_WEEKDAY)) AND BYTE#127;
END_FUNCTION_BLOCK

SETUP_WEEKDAYS2(WEEKDAYS2:=WEEKDAYS2);
WEEKDAYS2:=SETUP_WEEKDAYS2.WEEKDAYS2;
SETUP_LANGUAGE(LANGUAGE:=LANGUAGE);
LANGUAGE:=SETUP_LANGUAGE.LANGUAGE;
IF LANG = 0 THEN ly := LANGUAGE.DEFAULT; ELSE ly := MIN(LANG, LANGUAGE.LMAX); END_IF;
TRIM(str:=WDAY);
LOWERCASE(str:=TRIM.trim);
tmp:=LOWERCASE.lowercase;
CAPITALIZE(str:=LOWERCASE.lowercase);
tmp:=CAPITALIZE.CAPITALIZE;
FOR i := 1 TO 7 DO
	IF EQ_STRING(WEEKDAYS2[ly][i],tmp) THEN
		FSTRING_TO_WEEKDAY := i;
		RETURN;
	END_IF;
END_FOR;
DEC_TO_INT(DEC:=WDAY);
FSTRING_TO_WEEKDAY:=DEC_TO_INT.DEC_TO_INT;
END_FUNCTION_BLOCK

CASE step OF
00:	IF ACTIVATE AND NOT activate_last THEN
		ftp_file_size := UDINT#0;
		TIMEOUT := MAX(T#10s,TIMEOUT);
		timeout2 := TIMEOUT + T#1s;
		timeout3 := DIV_T_AI(TIMEOUT,2);
		DONE := FALSE;
		ip_c1_red_disable := FALSE;
		ip_c2_red_disable := FALSE;
		ERROR_C := DWORD#0;
		ERROR_T := BYTE#0;
		FSD.ERROR := BYTE#0;
		STRING_TO_URL(STR:=FTP_URL,DEFAULT_PROTOCOL:='',DEFAULT_PATH:='/');
		URL_DATA := STRING_TO_URL.STRING_TO_URL;
		IF LEN(URL_DATA.USER) = 0 THEN
			URL_DATA.USER := 'Anonymous';
			URL_DATA.PASSWORD := 'User@';
		END_IF;
		FILE_PATH_SPLIT(FILENAME:=FILENAME,X:=fpd); 
		fpd := FILE_PATH_SPLIT.X;
		str1 := fpd.FILENAME; 
		FILE_PATH_SPLIT(FILENAME:=URL_DATA.PATH,X:=fpd); 
		fpd := FILE_PATH_SPLIT.X;
		IF LEN(fpd.FILENAME) = 0 THEN 
			ftp_path := CONCAT(URL_DATA.PATH,str1);
		ELSE
			ftp_path := URL_DATA.PATH;
		END_IF;
		step := 10;
	END_IF;
10:	IF DNS_CLIENT.DONE THEN
		step := 20;
	ELSIF DNS_CLIENT.ERROR <> DWORD#0 THEN
		ERROR_C := DNS_CLIENT.ERROR;
		ERROR_T := BYTE#1;
		step := 980;
	END_IF;
20:	
	IP_C1.C_PORT := WORD#21; 
  	IP_C1.C_IP := DNS_CLIENT.IP4; 
  	IP_C1.C_MODE := BYTE#0; 
  	IP_C1.TIME_RESET := TRUE; 
  	IP_C1.C_ENABLE := TRUE; 
  	IP_C1.R_OBSERVE := TRUE; 
	R_BUF1.SIZE := UINT#0;
  	IP_C2.C_ENABLE   := FALSE; 
	step := 30;
30:	IF rcv_state = 220 THEN 
		snd_text := CONCAT('USER ',URL_DATA.USER);
		next_step := 40;
	END_IF;
40:	IF rcv_state = 331 THEN 
		snd_text := CONCAT('PASS ',URL_DATA.PASSWORD);
		next_step := 50;
	ELSIF rcv_state = 230 THEN 
		next_step := 50;
	ELSIF rcv_state = 220 THEN 
		next_step := 20; 
	END_IF;
50:	IF rcv_state = 230 THEN 
		snd_text := 'TYPE I';  
		next_step := 54;
	END_IF;
54:	IF rcv_state = 200 THEN 
		IF FTP_DOWNLOAD THEN 
			snd_text := CONCAT('SIZE ', ftp_path); 
			next_step := 56;
		ELSE
			step := 60;
		END_IF;
	END_IF;
56:	IF rcv_state = 213 THEN 
		ELEMENT_GET(SEP:=BYTE#32,POS:=1,ELEMENT:=rcv_text);
		rcv_text := ELEMENT_GET.ELEMENT;
		str1 := ELEMENT_GET.ELEMENT_GET;
		ftp_file_size := STRING_TO_UDINT(str1); 
		step := 60;
	END_IF;
60:	IF FTP_ACTIV THEN 
		IF URL_DATA.PORT = WORD#0 THEN
			URL_DATA.PORT := WORD#20; 
		END_IF;
		str2 := '';
		dw_tmp := PLC_IP4;
		FOR idx1 := 0 TO 5 DO
			IF idx1 = 4 THEN
				dw_tmp := ROR(WORD_TO_DWORD(URL_DATA.PORT),8);
			ELSE
				dw_tmp := ROL(dw_tmp,8);
			END_IF;
			str2 := CONCAT(str2,BYTE_TO_STRING(DWORD_TO_BYTE(dw_tmp),'%u'));
			IF idx1 < 5 THEN
				str2 := CONCAT(str2,',');
			END_IF;
		END_FOR;
		dw_tmp := DNS_CLIENT.IP4; 
		w_tmp := URL_DATA.PORT; 
		snd_text := CONCAT('PORT ',str2); 
		next_step := 80;
	ELSE
		snd_text := 'PASV';  
		next_step := 70;
	END_IF;
	step := 999; 
70:	IF rcv_state = 227 THEN 
		idx1 := FIND(rcv_text , '(' );
		idx2 := FIND(rcv_text , ')' );
		IF idx1 > 0 AND idx2 > idx1+1 THEN
			str1 := MID(rcv_text, idx2 - idx1 - 1, idx1+1);
			FOR idx1 := 0 TO 5 DO
				ELEMENT_GET(SEP:=BYTE#44,POS:=idx1,ELEMENT:=str1);
				str1 := ELEMENT_GET.ELEMENT;
				str2 := ELEMENT_GET.ELEMENT_GET;
				byar[idx1] := STRING_TO_BYTE(str2);
			END_FOR;
			dw_tmp := DWORD_OF_BYTE(byar[0],byar[1],byar[2],byar[3]); 
			w_tmp := WORD_OF_BYTE(byar[4],byar[5]); 
		END_IF;
		step := 100;
	END_IF;
80:	IF rcv_state = 200 THEN 
		step := 100;
	END_IF;
100:IP_C2.C_MODE := SEL(FTP_ACTIV,BYTE#0,BYTE#2); 
	IP_C2.C_IP := dw_tmp; 
	IP_C2.C_PORT := w_tmp; 
  	IP_C2.TIME_RESET := TRUE; 
  	IP_C2.C_ENABLE := TRUE; 
	IP_C2.R_OBSERVE := FALSE; 
	R_BUF2.SIZE := UINT#0;
	step := 120;
120:IF IP_C2.C_STATE > BYTE#127 THEN 
		IF FTP_DOWNLOAD THEN 
			IP_C2.MAILBOX[3] := BYTE#1; 
			step := 400;
		ELSE
			snd_text := 'STOR ';
			next_step := 140;
			snd_text := CONCAT(snd_text, ftp_path); 
			step := 999; 
		END_IF;
	END_IF;
140:IF rcv_state = 125 OR rcv_state = 150 THEN 
		step := 160;
	END_IF;
160:FSD.FILENAME := FILENAME; 
	FSD.MODE := BYTE#1; 
	FSD.OFFSET := UDINT#0; 
	FSD.AUTO_CLOSE := T#0s; 
	S_BUF2.SIZE := UINT#65535; 
	IP_C2.MAILBOX[2] := BYTE#1; 
	step := 200;
200:IF FSD.MODE = BYTE#0 AND FSD.ERROR = BYTE#0 THEN
		IP_C2.MAILBOX[2] := BYTE#0; 
		step := 210;
	END_IF;
210:IF S_BUF2.SIZE = UINT#0 THEN 
		IF FSD.FILE_SIZE - FSD.OFFSET > UDINT#0 THEN
			FSD.MODE := BYTE#1; 
			S_BUF2.SIZE := UINT#65535; 
			IP_C2.MAILBOX[2] := BYTE#1; 
			step := 200;
		ELSE
			IP_C2.C_ENABLE := FALSE; 
			step := 300;
		END_IF;
	END_IF;
300:IF rcv_state = 226 THEN 
		snd_text := 'QUIT';
		ip_c1_red_disable := TRUE;
		next_step := 320;
	END_IF;
320:IF rcv_state = 221 OR TON_WAIT.ET > timeout3  THEN 
		IP_C1.C_ENABLE := FALSE; 
		IF FILE_DELETE THEN 
			FSD.MODE := BYTE#4; 
			step := 340;
		ELSE
			step := 900;
		END_IF;
	END_IF;
340:IF FSD.MODE = BYTE#0 AND FSD.ERROR = BYTE#0 THEN
		step := 900;
	END_IF;
400:snd_text := 'RETR ';
	next_step := 410;
	snd_text := CONCAT(snd_text, ftp_path); 
	step := 999; 
410:IF rcv_state = 125 OR rcv_state = 150 THEN 
		IP_C2.R_OBSERVE := TRUE; 
		step := 420;
	END_IF;
420:FSD.FILENAME := FILENAME; 
	FSD.MODE := BYTE#3; 
	FSD.OFFSET := UDINT#0; 
	FSD.AUTO_CLOSE := T#0s; 
	step := 460;
440:IF R_BUF2.SIZE > UINT#0 THEN 
		IP_C2.MAILBOX[3] := BYTE#1; 
		FSD.MODE := BYTE#3; 
		step := 460;
	ELSIF FSD.FILE_SIZE = ftp_file_size THEN 
		IP_C2.C_ENABLE := FALSE; 
		ip_c2_red_disable := TRUE;
		step := 700;
	END_IF;
460:IF FSD.MODE = BYTE#0 AND FSD.ERROR = BYTE#0 THEN 
		R_BUF2.SIZE := UINT#0; 
		IP_C2.MAILBOX[3] := BYTE#0; 
		step := 440;
	END_IF;
700:IF rcv_state = 226 OR  TON_WAIT.ET > timeout3 THEN 
		IF FTP_DOWNLOAD AND FILE_DELETE THEN 
			snd_text := CONCAT('DELE ', ftp_path); 
			next_step := 720;
		ELSE
			step := 740;
		END_IF;
	END_IF;
720:IF rcv_state = 250 THEN 
		step := 740;
	END_IF;
740:snd_text := 'QUIT';
	ip_c1_red_disable := TRUE;
	next_step := 760;
	step := 999; 
760:IF rcv_state = 221 OR TON_WAIT.ET > timeout3 THEN 
		IP_C1.C_ENABLE := FALSE; 
		IF NOT FTP_DOWNLOAD AND FILE_DELETE THEN 
			FSD.MODE := BYTE#4; 
			step := 780;
		ELSE
			step := 900;
		END_IF;
	END_IF;
780:IF FSD.MODE = BYTE#0 AND FSD.ERROR = BYTE#0 THEN
		step := 900;
	END_IF;
900:DONE := TRUE;
	step := 980;
980:IP_C1.C_ENABLE := FALSE; 
	IP_C2.C_ENABLE := FALSE; 
	IP_C2.MAILBOX[2] := BYTE#0; 
	IP_C2.MAILBOX[3] := BYTE#0; 
	S_BUF1.SIZE := UINT#0;
	S_BUF2.SIZE := UINT#0;
	R_BUF1.SIZE := UINT#0;
	R_BUF2.SIZE := UINT#0;
	ftp_file_size := UDINT#0;
	snd_step := 0;
	next_step := 0;
	FSD.MODE := BYTE#5; 
	step := 990;
990:IF IP_C1.C_STATE = BYTE#0 AND IP_C2.C_STATE = BYTE#0 AND FSD.FILE_OPEN = FALSE THEN
		step := 0;
	END_IF;
999: ; 
END_CASE;
IF step >= 30 THEN
	IF R_BUF1.SIZE > UINT#0 THEN 
		idx1 := UINT_TO_INT(R_BUF1.SIZE);
		REPEAT 
			idx1 := idx1 - 1;
		UNTIL idx1 = 0 OR R_BUF1.BUFFER[idx1] >= BYTE#32 
		END_REPEAT;
		idx1 := idx1 + 1; 
		BUFFER_TO_STRING(PT:=R_BUF1.BUFFER,SIZE:=INT_TO_UINT(idx1),START:=UINT#0,STOP:=UINT#249);
		R_BUF1.BUFFER := BUFFER_TO_STRING.PT;
		rcv_text := BUFFER_TO_STRING.BUFFER_TO_STRING;
		IF LEN(rcv_text) >= 3 THEN 
			str1 := LEFT(rcv_text,3);
			IS_NUM(STR:=str1);
			IF IS_NUM.IS_NUM THEN 
				rcv_state := STRING_TO_INT(str1);
			END_IF;
			IP_C1.R_OBSERVE := FALSE;
		END_IF;
		R_BUF1.SIZE := UINT#0; 
	END_IF;
END_IF;
CASE snd_step OF
00:	IF LEN(snd_text) > 0 THEN
		_STRING_TO_BUFFER(STR:=snd_text,POS:=0,SIZE:=UINT#4096,PT:=S_BUF1.BUFFER); 
		S_BUF1.BUFFER := _STRING_TO_BUFFER.PT;
		idx1 := LEN(snd_text);
		S_BUF1.BUFFER[idx1] := BYTE#16#0D;
		idx1 := idx1 + 1;
		S_BUF1.BUFFER[idx1] := BYTE#16#0A;
		idx1 := idx1 + 1;
		S_BUF1.SIZE := INT_TO_UINT(idx1); 
		R_BUF1.SIZE := UINT#0; 
		IP_C1.R_OBSERVE := TRUE;
		rcv_state := 9999; 
		snd_text := '';
		snd_step := 10;
	END_IF;
10:	IF S_BUF1.SIZE = UINT#0 THEN 
		step := next_step;
		snd_step := 0;
	END_IF;
END_CASE;
IF ERROR_T = BYTE#0 AND step > 20 THEN 
	IF IP_C1.ERROR > DWORD#0 AND IP_C1.C_ENABLE AND NOT IP_C1.TIME_RESET THEN  
		IF ip_c1_red_disable = FALSE OR IP_C1.ERROR <> DWORD#16#FD000000 THEN
			ERROR_C := IP_C1.ERROR;
			ERROR_T := BYTE#2;
			step := 980;
		END_IF;
	END_IF;
	IF IP_C2.ERROR > DWORD#0 AND IP_C2.C_ENABLE AND NOT IP_C2.TIME_RESET THEN  
		IF ip_c2_red_disable = FALSE OR IP_C2.ERROR <> DWORD#16#FD000000 THEN
			ERROR_C := IP_C2.ERROR;
			ERROR_T := BYTE#3;
			step := 980;
		END_IF;
	END_IF;
	IF FSD.MODE = BYTE#0 THEN
		IF FSD.ERROR > BYTE#0 THEN
			ERROR_C := BYTE_TO_DWORD(FSD.ERROR);
			ERROR_T := BYTE#4; 
			step := 980;
		END_IF;
	END_IF;
END_IF;
IF TON_WAIT.Q THEN 
	ERROR_C := SHL(INT_TO_DWORD(step),16) OR INT_TO_DWORD(rcv_state); 
	ERROR_T := BYTE#5;
	step := 980;
END_IF;
DNS_CLIENT(IP_C:=IP_C1, S_BUF:=S_BUF1, R_BUF:=R_BUF1, DOMAIN:=URL_DATA.DOMAIN, IP4_DNS:= DNS_IP4, ACTIVATE:=step=10); 
IP_C1  := DNS_CLIENT.IP_C;
R_BUF1 := DNS_CLIENT.R_BUF;
S_BUF1 := DNS_CLIENT.S_BUF;
IPC1(IP:= DWORD#0, PORT:= WORD#0 , TIME_OUT:= TIMEOUT, IP_C:= IP_C1, S_BUF:= S_BUF1, R_BUF:= R_BUF1); 
IP_C1  := IPC1.IP_C;
R_BUF1 := IPC1.R_BUF;
S_BUF1 := IPC1.S_BUF;
IPC2(IP:= DWORD#0, PORT:= WORD#0 , TIME_OUT:= TIMEOUT, IP_C:= IP_C2, S_BUF:= S_BUF2, R_BUF:= R_BUF2); 
IP_C2  := IPC2.IP_C;
R_BUF2 := IPC2.R_BUF;
S_BUF2 := IPC2.S_BUF;
TON_WAIT(IN:=step = last_step AND step > 0,PT:=timeout2);
last_step := step;
activate_last := ACTIVATE;
BUSY := step <> 0;
IF FTP_DOWNLOAD THEN 
	FS(FSD:=FSD,PT:=R_BUF2); 
	FSD    := FS.FSD;
	R_BUF2 := FS.PT;
ELSE
	FS(FSD:=FSD,PT:=S_BUF2); 
	FSD	   := FS.FSD;
	S_BUF2 := FS.PT;
END_IF;
END_FUNCTION_BLOCK

buff.N := LIMIT(0, N, 32);
IF NOT init OR rst THEN
	FOR i := 1 TO N DO
		buff(in := in);
	END_FOR;
	avg := in;
	init := TRUE;
ELSIF E THEN
	buff(in := in);
	avg := avg + (in - buff.out ) / INT_TO_REAL(N);
END_IF;
END_FUNCTION_BLOCK

T_PLC_US();
tx:= T_PLC_US.T_PLC_US;
tc := UDINT_TO_REAL(tx - last);
IF NOT init THEN
	init := TRUE;
	old := in;
ELSIF run AND tc > 0.0 THEN
	out := (in - old) / tc * 1000000.0 * K;
	old := in;
ELSE
	out := 0.0;
END_IF;
last := tx;
T_PLC_US();
tx:= T_PLC_US.T_PLC_US;
IF NOT init THEN
	init := TRUE;
ELSIF run AND tx - last > UDINT#0 THEN
	out := (in - old) / UDINT_TO_REAL(tx - last) * 1000000.0 * K;
ELSE
	out := 0.0;
END_IF;
old := in;
last := tx;
END_FUNCTION_BLOCK

T1(in:= in, T:=T);
out := (in - t1.out) * K;
END_FUNCTION_BLOCK

IF rst THEN
	out := 0.0;
ELSE
	integ(X := IN, E := RUN, K := K, Y := out);
	out := integ.Y;
END_IF;
IF out >= OUT_MAX THEN
	out := out_max;
	LIM := TRUE;
ELSIF out <= out_min THEN
	out := out_min;
	lim := TRUE;
ELSE
	lim := FALSE;
END_IF;
END_FUNCTION_BLOCK

IF RST THEN
	R2_SET(X:=0.0);
	val:=R2_SET.R2_SET;
	out := 0.0;
ELSE
	integ(X := IN, E := RUN, K := K, Y := ix);
	ix := integ.Y;
	R2_ADD(X:=val,Y:=ix);
	val:=R2_ADD.R2_ADD;
	ix := 0.0;
	OUT := val.RX;
END_IF;
IF out > OUT_MIN AND out < OUT_MAX THEN
	LIM := FALSE;
ELSE
	OUT := LIMIT(OUT_MIN, OUT, OUT_MAX);
	R2_SET(X:=OUT);
	val:=R2_SET.R2_SET;
	LIM := TRUE;
END_IF;
END_FUNCTION_BLOCK

IF (rst = TRUE) OR (init = FALSE) THEN
  mn := in;
  mx := in;
  init := TRUE;
ELSIF (in < mn) THEN
  mn := in;
ELSIF (in > mx) THEN
  mx := in;
END_IF;
END_FUNCTION_BLOCK

diff(IN := IN, K := TV);
Y := KP * (diff.out + IN);
END_FUNCTION_BLOCK

diff(IN := IN, K := TV);
tp(in := diff.out, T := REAL_TO_TIME(T1));
Y := KP * (tp.out + IN);
END_FUNCTION_BLOCK

integ(IN := IN, K := KI, RUN := IEN, RST := RST, OUT_MIN := ILIM_L, OUT_MAX := ILIM_H);
LIM := integ.LIM;
Y := KP * IN + integ.Out;
END_FUNCTION_BLOCK

IF TN > 0.0 THEN
	integ(IN := IN, K := 1.0 / TN, RUN := IEN, RST := RST, OUT_MIN := ILIM_L, OUT_MAX := ILIM_H);
ELSE
	integ(RST := FALSE);
END_IF;
