            IF pos+12 > LEN(HTML_DECODE) THEN
	            size := LEN(HTML_DECODE) - pos - 1;
	        ELSE
	            size := 10;
	        END_IF; 
		    tmp := MID(HTML_DECODE, size, pos + 2);
