		ELSE
			text := ' HTTP/1.0';
		END_IF;
		text := CONCAT(text,delimiter2b);
		_STRING_TO_BUFFER(STR:=text,POS:=idx,PT:=S_BUF.BUFFER,SIZE:=UINT#4096); 
		S_BUF.BUFFER:=_STRING_TO_BUFFER.pt;
		idx := idx + LEN(text);
		IF MODE = BYTE#1 THEN 
			text := CONCAT('Connection: Keep-Alive',delimiter2b); 
		ELSIF MODE = BYTE#3 THEN 
			text := CONCAT('Connection: Close',delimiter2b); 
		ELSE
			text := '';
		END_IF;
		text := CONCAT(text,URL_DATA.HEADER);
		_STRING_TO_BUFFER(STR:=text,POS:=idx,PT:=S_BUF.BUFFER,SIZE:=UINT#4096); 
		S_BUF.BUFFER:=_STRING_TO_BUFFER.pt;
		idx := idx + LEN(text);
