		k_idx := 0;
		i := UDINT_TO_INT(OFFSET);
		size := UINT_TO_INT(PT.SIZE) - 1;
		RESULT := BYTE#0;
		state := BYTE#5; 
		step := 0; 
	END_IF;
	watchdog(IN:=FALSE,PT:=T#1ms); 
	watchdog.IN := TRUE;
	WHILE (state = BYTE#5) DO 
		watchdog(); 
		IF watchdog.Q THEN 
			state := BYTE#5;
			EXIT;
		ELSIF i > size THEN 
			state := BYTE#10; 
			EXIT;
		ELSE
			c := PT.BUFFER[i]; 
			eof := INT_TO_UINT(i + 1) = PT.SIZE; 
			k_add := BYTE#0;
			v_add := BYTE#0;
			CASE step OF
			0: 
				IF c = BYTE#91 THEN 
					step := 200; 
				ELSIF c = BYTE#59 OR c = BYTE#35 THEN 
					step := 100; 
				ELSIF c > BYTE#32 THEN 
					k_add := c; 
					step := 300; 
				END_IF;
			100: 
				IF c < BYTE#32 THEN 
					state  := BYTE#3; 
				END_IF;
			200: 
				IF c = BYTE#93 THEN 
					IF k_idx > 0 THEN 
						state  := BYTE#1; 
					ELSE
						KEY := '';
						k_idx := 0;
						step := 0; 
					END_IF;
				ELSIF c < BYTE#32 OR eof THEN 
					KEY := '';
					k_idx := 0;
					step := 0;
				ELSE
					k_add := c; 
				END_IF;
			300: 
				IF c < BYTE#32 THEN 
						KEY := '';
						k_idx := 0;
					step := 0;
				ELSIF c = BYTE#61 THEN 
					step := 330;
				ELSE
					k_add := c; 
				END_IF;
			330: 
				IF c < BYTE#32 THEN 
					state := BYTE#2; 
				ELSIF eof THEN
					state := BYTE#2; 
					v_add := c; 
				ELSE
					v_add := c; 
					step := 350;
				END_IF;
			350: 
				IF c < BYTE#32 THEN 
					state := BYTE#2; 
				ELSIF eof THEN
					v_add := c; 
					state := BYTE#2; 
				ELSE
					v_add := c; 
				END_IF;
			END_CASE;
			IF v_add > BYTE#0 AND v_idx < 250 THEN 
				v_buf[v_idx] := v_add;
				v_idx := v_idx + 1;
			END_IF;
			IF k_add > BYTE#0 AND k_idx < 250 THEN 
				k_buf[k_idx] := k_add;
				k_idx := k_idx + 1;
			END_IF;
			i := i + 1; 
		END_IF;
	END_WHILE;
	IF (state = BYTE#1 OR state = BYTE#2) AND k_idx > 0 THEN 
		BUFFER_TO_STRING(PT:=k_buf,SIZE:=INT_TO_UINT(k_idx),START:=UINT#0,STOP:=UINT#249);
		k_buf := BUFFER_TO_STRING.PT;
