				RESULT := BYTE#1; 
				OFFSET := INT_TO_UDINT(i); 
				RUN := BYTE#0;
				state := BYTE#0;
			END_IF;
		ELSE
			KEY := '';
			k_idx := 0;
			RESULT := BYTE#11; 
			RUN := BYTE#0;
			state := BYTE#0;
		END_IF;
