		IF RUN = BYTE#2 OR RUN = BYTE#3 THEN 
			IF EQ_STRING(KEY,STR) OR LEN(STR) = 0 THEN 
				RESULT := BYTE#2; 
				OFFSET := INT_TO_UDINT(i); 
				RUN := BYTE#0;
				state := BYTE#0;
			END_IF;
		END_IF;
	03:	
		OFFSET := INT_TO_UDINT(i); 
		state := BYTE#0;
	05:	RESULT := BYTE#5; 
	10:	
		RESULT := BYTE#10; 
		OFFSET := INT_TO_UDINT(i); 
		RUN := BYTE#0;
		state := BYTE#0;
