				END_IF;
			300: 
				IF c < BYTE#32 THEN 
					KEY := '';
					k_idx := 0;
					step := 0;
				ELSIF c = BYTE#61 THEN 
					step := 330;
				ELSE
					k_add := c; 
				END_IF;
			330: 
				IF c < BYTE#32 THEN 
					state := BYTE#2; 
				ELSIF eof THEN
					state := BYTE#2; 
					v_add := c; 
				ELSE
					v_add := c; 
					step := 350;
				END_IF;
			350: 
				IF c < BYTE#32 THEN 
					state := BYTE#2; 
				ELSIF eof THEN
					v_add := c; 
					state := BYTE#2; 
				ELSE
					v_add := c; 
				END_IF;
			END_CASE;
			IF v_add > BYTE#0 AND v_idx < 250 THEN 
				v_buf[v_idx] := v_add;
				v_idx := v_idx + 1;
			END_IF;
			IF k_add > BYTE#0 AND k_idx < 250 THEN 
				k_buf[k_idx] := k_add;
				k_idx := k_idx + 1;
			END_IF;
			i := i + UDINT#1; 
		END_IF;
	END_WHILE;
	IF (state = BYTE#1 OR state = BYTE#2) AND k_idx > 0 THEN 
		BUFFER_TO_STRING(PT:=k_buf,SIZE:=INT_TO_UINT(k_idx),START:=UINT#0,STOP:=UINT#249);
		k_buf := BUFFER_TO_STRING.PT;
		KEY   := BUFFER_TO_STRING.BUFFER_TO_STRING;
	END_IF;
	IF state = BYTE#2 AND v_idx > 0 THEN 
		BUFFER_TO_STRING(PT:=v_buf,SIZE:=INT_TO_UINT(v_idx),START:=UINT#0,STOP:=UINT#249);
		v_buf := BUFFER_TO_STRING.PT;
		VALUE := BUFFER_TO_STRING.BUFFER_TO_STRING;
	END_IF;
	CASE _BYTE_TO_INT(state) OF
	01:	
		IF RUN = BYTE#1 OR RUN = BYTE#3 THEN 
			IF EQ_STRING(KEY,STR) OR LEN(STR) = 0 THEN 
				RESULT := BYTE#1; 
				OFFSET := i; 
				RUN := BYTE#0;
				state := BYTE#0;
			END_IF;
		ELSE
			KEY := '';
			k_idx := 0;
			RESULT := BYTE#11; 
			RUN := BYTE#0;
			state := BYTE#0;
		END_IF;
	02:	
		IF RUN = BYTE#2 OR RUN = BYTE#3 THEN 
			IF EQ_STRING(KEY,STR) OR LEN(STR) = 0 THEN 
				RESULT := BYTE#2; 
				OFFSET := i; 
				RUN := BYTE#0;
				state := BYTE#0;
			END_IF;
		END_IF;
	03:	
		OFFSET := i; 
		state := BYTE#0;
	05:	RESULT := BYTE#5; 
	10:	
		RESULT := BYTE#10; 
		OFFSET := i; 
		RUN := BYTE#0;
		state := BYTE#0;
	END_CASE;
END_IF;
END_FUNCTION_BLOCK

