	IF mode <> lmode THEN
		out := BYTE#0;
		last := BYTE#0;
		old := BYTE#0;
		lmode := mode;
	END_IF;
	in:=BIT_LOAD_B(in,I0,0); 
	in:=BIT_LOAD_B(in,I1,1); 
	in:=BIT_LOAD_B(in,I2,2); 
	in:=BIT_LOAD_B(in,I3,3); 
	IF in <> last THEN
		CASE mode OF
			0:	
				out := in;
			1:	
				IF    (in AND BYTE#2#00001000) > BYTE#0  THEN out := BYTE#8;
				ELSIF (in AND BYTE#2#00000100) > BYTE#0  THEN out := BYTE#4;
				ELSIF (in AND BYTE#2#00000010) > BYTE#0  THEN out := BYTE#2;
				ELSE out := in;
				END_IF;
			2:	
				last := ((in XOR last) AND in);
				IF    (last AND BYTE#2#00001000) > BYTE#0  THEN out := BYTE#8;
				ELSIF (last AND BYTE#2#00000100) > BYTE#0  THEN out := BYTE#4;
				ELSIF (last AND BYTE#2#00000010) > BYTE#0  THEN out := BYTE#2;
				ELSE out := last;
				END_IF;
			3:	
				IF (out AND in) = BYTE#0 THEN
					IF    (in AND BYTE#2#00001000) > BYTE#0  THEN out := BYTE#8;
					ELSIF (in AND BYTE#2#00000100) > BYTE#0  THEN out := BYTE#4;
					ELSIF (in AND BYTE#2#00000010) > BYTE#0  THEN out := BYTE#2;
					ELSE out := in;
					END_IF;
				END_IF;
		END_CASE;
		last := in;
	END_IF;
	tp := out <> old;
	old := out;
ELSE
	out := BYTE#0;
	last := BYTE#0;
	old := BYTE#0;
	lmode := 0;
	tp := FALSE;
END_IF;
END_FUNCTION_BLOCK

