	ELSE
		count := count + DWORD_TO_INT(SHR_DWORD(DINT_TO_DWORD(INT_TO_DINT(month) - INT_TO_DINT(4)),1));
	END_IF;
	IF SHL_WORD(INT_TO_WORD(year),14) = WORD#0 THEN
		count := count + 1;
	END_IF;
ELSE
	count := (month - 1) * 31;
END_IF;
