				buf[start] := buf[i];
				buf[i] := temp;
			END_IF;
		END_FOR;
	END_FOR;
	stop := M - 1 - d2;
	start := d2;
	IF NOT even(INT_TO_DINT(disc)) THEN start := start + 1; END_IF;
	avg := 0.0;
	FOR i := start TO stop DO avg := avg + buf[i]; END_FOR;
	avg := avg / INT_TO_REAL(stop - start +1);
	low := buf[start];
	high := buf[stop];
ELSE
	Trig := FALSE;
END_IF;
END_FUNCTION_BLOCK

