       st_CHAR,INT#1,Xus_TN_INPUT_CONTROL_DATA.in_Cursor_Pos);
      in_CursorOffset := INT#1;
      Xus_TN_INPUT_CONTROL_DATA.bo_Update_Input := TRUE;
    END_IF;
  END_IF;
  CASE _BYTE_TO_INT(Xus_TN_INPUT_CONTROL_DATA.by_Input_Exten_Code) OF
  67: 
    in_CursorOffset := INT#1;
  68: 
    in_CursorOffset := INT#-1;  
  08: 
