    ELEMENT_GET(ELEMENT:=Xus_TN_MENU_POPUP.st_Menu_Text,SEP:=BYTE#35,POS:=in_Count-1);
	Xus_TN_MENU_POPUP.st_Menu_Text:=ELEMENT_GET.ELEMENT;
