CASE DATA.D_MODE OF
01:	x := WORD_TO_INT(DATA.D_HEAD AND WORD#16#00FF);
	CASE x OF
	01:	cnt := LEN(DATA.D_STRING); 
	02:	cnt := 4; 
		REAL_TO_DW(X:=DATA.D_REAL);
		tmp_dw2 := REAL_TO_DW.REAL_TO_DW;
	03:	cnt := 4; 
		tmp_dw2 := DATA.D_DWORD;
	ELSE
		cnt := 0;
	END_CASE;
	pTmp := 1;
	IF (cnt + HeaderSize) > (buf_totalsize - DATA.BUF_SIZE) THEN 
		RETURN;
	END_IF;
	mode_last := DATA.D_MODE;
	tmp_dw := SHL(WORD_TO_DWORD(DATA.D_HEAD),16) OR INT_TO_DWORD(cnt);
	n1 := 0;
	idx := DATA._Last;
	REPEAT
		n2 := MIN(HeaderSize - n1, buf_totalsize - idx);
		FOR n := 1 TO n2 DO
			tmp_dw := ROL(tmp_dw,8);
			data.BUF[idx] := DWORD_TO_BYTE(tmp_dw);
			idx := idx + 1;
		END_FOR;
		IF idx >= buf_totalsize THEN
			idx := 0;
		END_IF;
		n1 := n1 + n2;
	UNTIL n1 >= HeaderSize
	END_REPEAT;
	n1 := 0;
	REPEAT
		n2 := MIN(cnt - n1, buf_totalsize - idx);
		IF x = 1 THEN 
			FOR n := 1 TO n2 DO
				data.BUF[idx] := INT_TO_BYTE(GET_CHAR(DATA.D_STRING,pTmp));
				pTmp := pTmp + 1;
				idx := idx + 1;
			END_FOR;
		ELSE 
			FOR n := 1 TO n2 DO
				tmp_dw2 := ROL(tmp_dw2,8);
				data.BUF[idx] := DWORD_TO_BYTE(tmp_dw2);
				idx := idx + 1;
			END_FOR;
		END_IF;
		IF idx >= buf_totalsize THEN
			idx := 0;
		END_IF;
		n1 := n1 + n2;
	UNTIL n1 >= cnt
	END_REPEAT;
	DATA._Last := idx;
	DATA.BUF_SIZE := DATA.BUF_SIZE + cnt + HeaderSize;
	DATA.BUF_COUNT := DATA.BUF_COUNT + 1;
	DATA.BUF_USED := INT_TO_USINT(100 * DATA.BUF_SIZE / buf_totalsize); 
	DATA.D_MODE := 0;
10..12: 
	IF DATA.D_MODE <> 11 THEN
		IF DATA.BUF_COUNT = 0 THEN RETURN; END_IF;
		DATA._GetEnd := DATA._First;
		mode_last := DATA.D_MODE;
		n1 := 0;
		tmp_dw := DWORD#0;
		idx := DATA._GetEnd;
		REPEAT
			n2 := MIN(HeaderSize - n1, buf_totalsize - idx);
			FOR n := 1 TO n2 DO
				tmp_dw := ROL(tmp_dw,8) OR BYTE_TO_DWORD(data.BUF[idx]);
				idx := idx + 1;
			END_FOR;
			IF idx >= buf_totalsize THEN
				idx := 0;
			END_IF;
			n1 := n1 + n2;
		UNTIL n1 >= HeaderSize
		END_REPEAT;
		DATA._GetEnd := idx;
		DATA._GetStart := DATA._GetEnd;
		cnt := DWORD_TO_INT(tmp_dw AND DWORD#16#0000_FFFF);
		DATA.D_HEAD := DWORD_TO_WORD(SHR(tmp_dw,16));
		x := WORD_TO_INT(DATA.D_HEAD AND WORD#16#00FF);
		IF x = 1 THEN
			DATA.D_STRING := '';
		END_IF;
		tmp_dw2 := DWORD#0;
		n1 := 0;
		idx := DATA._GetEnd;
		REPEAT
			n2 := MIN(cnt - n1, buf_totalsize - idx);
			IF x = 1 THEN 
				FOR n := 1 TO n2 DO
					DATA.D_STRING := CONCAT(DATA.D_STRING,BYTE_TO_STRING(data.BUF[idx],'%c'));
					idx := idx + 1;
				END_FOR;
			ELSE 
				FOR n := 1 TO n2 DO
					tmp_dw2 := ROL(tmp_dw2,8) OR BYTE_TO_DWORD(data.BUF[idx]);
					idx := idx + 1;
				END_FOR;
			END_IF;
			IF idx >= buf_totalsize THEN
				idx := 0;
			END_IF;
			n1 := n1 + n2;
		UNTIL n1 >= cnt
		END_REPEAT;
		DATA._GetEnd := idx;
		CASE x OF
		02:	DW_TO_REAL(X:=tmp_dw2); 
			DATA.D_REAL:=DW_TO_REAL.DW_TO_REAL;
		03:	DATA.D_DWORD := tmp_dw2; 
		END_CASE;
		DATA.D_MODE := 0;
	END_IF;
	IF (mode_last = 10 AND DATA.D_MODE = 11) OR (mode_last = 12 AND DATA.D_MODE = 0) THEN 
		mode_last := DATA.D_MODE;
		DATA.BUF_SIZE := DATA.BUF_SIZE - cnt - HeaderSize;
		DATA.BUF_COUNT := DATA.BUF_COUNT - 1;
		DATA._First := DATA._GetEnd;
		DATA.BUF_USED := INT_TO_USINT(100 * DATA.BUF_SIZE / buf_totalsize); 
		DATA.D_MODE := 0;
	END_IF;
99:	
	DATA._First := INT#0;
	DATA._Last := INT#0;
	DATA._GetStart := INT#0;
	DATA._GetEnd := INT#0;
	DATA.BUF_COUNT := INT#0;
	DATA.BUF_SIZE := INT#0;
	DATA.BUF_USED := USINT#0;
	DATA.D_STRING := '';
	DATA.D_DWORD := DWORD#0;
	DATA.D_REAL := 0.0;
	DATA.D_HEAD := WORD#0;
	DATA.D_MODE := 0;
	mode_last := 0;
END_CASE;
END_FUNCTION_BLOCK

