HTTP_GET();
IP_C     := HTTP_GET.IP_C;
S_BUF    := HTTP_GET.S_BUF;
R_BUF    := HTTP_GET.R_BUF;
URL_DATA := HTTP_GET.URL_DATA;
CPB(SEP:=sep,RUN:=run,OFFSET:=offset,VALUE:=value,PT:=R_BUF); 
run:=CPB.RUN;
offset:=CPB.OFFSET;
value:=CPB.VALUE;
R_BUF:=CPB.PT;
result:=CPB.RESULT;
