IF BIT_OF_DWORD(WORD_TO_DWORD(CTRL.COMMAND),15) THEN
  COMMAND := CTRL.COMMAND;
  CTRL.COMMAND := WORD#0;
  INDEX := UINT_TO_INT(CTRL.START_POS);
  STOP := UINT_TO_INT(CTRL.STOP_POS);
  MODE := 100;
  PATH_OVERFLOW := FALSE;
  CTRL.TYP := 0;
  CTRL.COUNT := UINT#00;
  CTRL.LEVEL := UINT#00;
  CTRL.ATTRIBUTE := '';
  CTRL.ELEMENT := '';
  CTRL.PATH := '';
  CTRL.VALUE := '';
  WATCHDOG.PT := CTRL.WATCHDOG;
END_IF;
IF INDEX < 0 THEN RETURN;END_IF;
CTRL.BLOCK1_START := UINT#0;
CTRL.BLOCK1_STOP := UINT#0;
CTRL.BLOCK2_START := UINT#0;
CTRL.BLOCK2_STOP := UINT#0;
WATCHDOG(IN:=FALSE); 
WHILE (TRUE) DO
  WATCHDOG(IN:=CTRL.WATCHDOG > T#0s);
  IF WATCHDOG.Q THEN
    CTRL.TYP := 98;
    RETURN;
  END_IF;
  IF INDEX>STOP THEN
    CTRL.COUNT := CTRL.COUNT + UINT#1;
    CTRL.TYP := 99;
    MODE  :=0; 
    INDEX :=0; 
    RETURN;
  END_IF;
  CASE MODE OF
  100: 
    s1 := 0;
    e1 := 0;
    WHILE (INDEX <= STOP) DO
      IF BUF[INDEX]=BYTE#60 THEN 
        INDEX := INDEX +1;
        C := BUF[INDEX];
        IF C=BYTE#47 THEN    
          MODE := 300;       
        ELSIF C=BYTE#33 THEN 
          INDEX := INDEX +1;
          MODE := 500;
        ELSE
          s1 := INDEX;
        END_IF;
        EXIT;
      END_IF;
      INDEX := INDEX+1;
    END_WHILE;
    CTRL.TYP := 0; 
    IF s1>0 THEN
      WHILE (INDEX <= STOP AND e1=0) DO
        C := BUF[INDEX];
	    IF C<=BYTE#32 THEN 
          INDEX2 := INDEX;
          WHILE (INDEX2 <= STOP) AND (BUF[INDEX2]<=BYTE#32) DO
            INDEX2 := INDEX2 + 1;
          END_WHILE;
		  IF BUF[INDEX2]=BYTE#47 THEN 
			  INDEX := INDEX2;
			  e1 := INDEX-2;
              CTRL.TYP := 1; 
   		      MODE := 300;    
              EXIT;
          END_IF;
          e1 := INDEX-1;  
          CTRL.TYP := 1; 
		  MODE := 400; 
        ELSIF C=BYTE#62 THEN 
		  INDEX2 := INDEX-1;
		  IF BUF[INDEX2]=BYTE#47 THEN 
            e1 := INDEX2-1;  
            CTRL.TYP := 1;
			EMPTY_TAG := TRUE; 
  	        MODE := 200;       
            EXIT;
          END_IF;
          e1 := INDEX-1;  
          INDEX2 := INDEX + 1;
          WHILE (INDEX2 <= STOP) DO
            C := BUF[INDEX2];
	        IF C=BYTE#60 THEN 
              INDEX2 := INDEX2 + 1; 
              C := BUF[INDEX2];
              INDEX2 := INDEX2 - 1;
              IF C=BYTE#47 THEN 
                EMPTY_TAG := TRUE;
                MODE := 200; 
              ELSE
   		        MODE := 100; 
              END_IF;
              CTRL.TYP := 1; 
              EXIT;
            ELSIF C>BYTE#32  THEN 
              CTRL.TYP := 1;      
              MODE := 200;
              EXIT;
            END_IF;
            INDEX2 := INDEX2 + 1;
          END_WHILE;
        END_IF;
        INDEX := INDEX + 1;
      END_WHILE;
    END_IF;
    IF CTRL.TYP > 0 THEN
      IF BUF[s1]=BYTE#63 THEN 
        s1 := s1+1; 
        CTRL.TYP := 5;
      END_IF;
      CTRL.BLOCK1_START := INT_TO_UINT(S1);
      CTRL.BLOCK1_STOP  := INT_TO_UINT(E1);
      BUFFER_TO_STRING(size:=INT_TO_UINT(STOP+1),start:=CTRL.BLOCK1_START,stop:=CTRL.BLOCK1_STOP,pt:=BUF);
      CTRL.ELEMENT:=BUFFER_TO_STRING.BUFFER_TO_STRING;
      BUF:=BUFFER_TO_STRING.pt;
      CTRL.COUNT := CTRL.COUNT + UINT#1;
      CTRL.LEVEL := CTRL.LEVEL + UINT#1; 
	  IF PATH_OVERFLOW = FALSE THEN
        IF LEN(CTRL.PATH) + LEN(CTRL.ELEMENT) + 1 > 255 THEN
          PATH_OVERFLOW := TRUE;
          CTRL.PATH := 'OVERFLOW';
        ELSE
          CTRL.PATH  := CONCAT(CTRL.PATH,'/');
          CTRL.PATH  := CONCAT(CTRL.PATH,CTRL.ELEMENT);
        END_IF;      
      END_IF;      
      IF BIT_OF_DWORD(WORD_TO_DWORD(COMMAND),CTRL.TYP) THEN
        RETURN;
      END_IF; 
    END_IF; 
  200: 
    CTRL.VALUE := '';
    IF EMPTY_TAG = FALSE THEN
      s1 := INDEX;
      WHILE (INDEX <= STOP) AND (BUF[INDEX]<>BYTE#60) DO
        INDEX := INDEX + 1;
      END_WHILE;
      E1 := INDEX-1;
      CTRL.BLOCK1_START := INT_TO_UINT(S1);
      CTRL.BLOCK1_STOP  := INT_TO_UINT(E1);
      BUFFER_TO_STRING(size:=INT_TO_UINT(STOP+1),start:=CTRL.BLOCK1_START,stop:=CTRL.BLOCK1_STOP,pt:=BUF);
      CTRL.VALUE:=BUFFER_TO_STRING.BUFFER_TO_STRING;
      BUF:=BUFFER_TO_STRING.pt;
    END_IF;
    EMPTY_TAG := FALSE;
    MODE := 300; 
    CTRL.COUNT := CTRL.COUNT + UINT#1;
    CTRL.TYP := 3;
    IF BIT_OF_DWORD(WORD_TO_DWORD(COMMAND),CTRL.TYP) THEN
      RETURN;
    END_IF;
  300: 
    WHILE (INDEX <= STOP) DO
	  C := BUF[INDEX];
      IF C=BYTE#62 THEN 
        INDEX := INDEX + 1;
        FINDB(str1:=CTRL.PATH,str2:='/');
		S1 := FINDB.FindB;
	    IF PATH_OVERFLOW = FALSE THEN
          IF S1>1 THEN
            CTRL.ELEMENT := RIGHT(CTRL.PATH,LEN(CTRL.PATH)-S1);
            CTRL.PATH := LEFT(CTRL.PATH,S1-1);
          ELSE
            CTRL.ELEMENT := RIGHT(CTRL.PATH,LEN(CTRL.PATH)-1);
            CTRL.PATH :='';
          END_IF;
        END_IF;
        CTRL.LEVEL := CTRL.LEVEL - UINT#1; 
        CTRL.COUNT := CTRL.COUNT + UINT#1;
        CTRL.TYP := 2; 
        MODE := 100; 
        IF BIT_OF_DWORD(WORD_TO_DWORD(COMMAND),CTRL.TYP) THEN
		  RETURN;
        ELSE
		  EXIT;
        END_IF;
      END_IF;
      INDEX := INDEX + 1;
    END_WHILE;
  400:  
    WHILE (INDEX <= STOP AND BUF[INDEX]<=BYTE#32) DO
      INDEX := INDEX + 1;
    END_WHILE;
    E1 := 0;
    S1 := INDEX;
    WHILE (INDEX <= STOP) DO
      IF BUF[INDEX]=BYTE#61 THEN 
	    E1 := INDEX-1;
	    EXIT;
	  END_IF;
      INDEX := INDEX + 1;
    END_WHILE;
    IF E1>0 THEN
      CTRL.BLOCK1_START := INT_TO_UINT(S1);
      CTRL.BLOCK1_STOP  := INT_TO_UINT(E1);
      BUFFER_TO_STRING(size:=INT_TO_UINT(STOP+1),start:=CTRL.BLOCK1_START,stop:=CTRL.BLOCK1_STOP,pt:=BUF);
      CTRL.ATTRIBUTE:=BUFFER_TO_STRING.BUFFER_TO_STRING;
      BUF:=BUFFER_TO_STRING.pt;
      INDEX := INDEX + 2;
      E1 := 0;
      S1 := INDEX;
      WHILE (INDEX <= STOP AND E1=0) DO
	    C := BUF[INDEX];
        IF C=BYTE#34 OR C=BYTE#39 THEN 
	      E1 := INDEX-1;
	    END_IF;
        INDEX := INDEX + 1;
      END_WHILE;
      IF E1>0 THEN
        CTRL.BLOCK2_START := INT_TO_UINT(S1);
        CTRL.BLOCK2_STOP  := INT_TO_UINT(E1);
	    BUFFER_TO_STRING(size:=INT_TO_UINT(STOP+1),start:=CTRL.BLOCK2_START,stop:=CTRL.BLOCK2_STOP,pt:=BUF);
        CTRL.VALUE:=BUFFER_TO_STRING.BUFFER_TO_STRING;
        BUF:=BUFFER_TO_STRING.pt;
        WHILE (INDEX <= STOP AND BUF[INDEX]<=BYTE#32) DO
          INDEX := INDEX + 1;
        END_WHILE;
        C := BUF[INDEX];
        IF C=BYTE#62 THEN
          INDEX := INDEX + 1;
          INDEX2 := INDEX;
          WHILE (INDEX <= STOP AND BUF[INDEX]<=BYTE#32) DO
            INDEX := INDEX + 1;
          END_WHILE;
          IF BUF[INDEX]=BYTE#60 THEN 
            MODE := 100; 
          ELSE
            INDEX := INDEX2;
            MODE := 200; 
          END_IF;
        ELSIF C=BYTE#47 OR C=BYTE#63 THEN 
          MODE := 300; 
        ELSE
          MODE := 400; 
        END_IF;
        CTRL.COUNT := CTRL.COUNT + UINT#1;
        CTRL.TYP := 4;
        IF BIT_OF_DWORD(WORD_TO_DWORD(COMMAND),CTRL.TYP) THEN
          RETURN;
        END_IF;
      END_IF;
    END_IF;
  500: 
    CTRL.TYP := 0;
    S1 := 0;
    INDEX2 := 11;
    WHILE (S1=0) DO
      INDEX2 := INDEX2 + 1;
      CTRL.TYP := INDEX2;
      CASE INDEX2 OF 
      12: 
	    S_CODE := '[CDATA[';
	    E_CODE := ']]>';
      13: 
	    S_CODE := '--';
	    E_CODE := '-->';
      14: 
	    E_CODE := '';
        S1 := INDEX;
        EXIT;       
      END_CASE;
      E1 := LEN(S_CODE);
      BUFFER_SEARCH(size:=INT_TO_UINT(INDEX+E1),str:=S_CODE,pos:=INDEX,ign:=FALSE,pt:=BUF);
      BUF:=BUFFER_SEARCH.pt;
      IF BUFFER_SEARCH.BUFFER_SEARCH = INDEX THEN
        S1 := INDEX+E1;
      END_IF;
    END_WHILE;
    CTRL.BLOCK1_START := INT_TO_UINT(S1);
    IF LEN(E_CODE)>0 THEN
      BUFFER_SEARCH(size:=INT_TO_UINT(STOP+1),str:=E_CODE,pos:=INDEX,ign:=FALSE,pt:=BUF);
      BUF:=BUFFER_SEARCH.pt;
      E1 := BUFFER_SEARCH.BUFFER_SEARCH;
      CTRL.BLOCK1_STOP := INT_TO_UINT(E1-1);
      INDEX := E1+LEN(E_CODE); 
    ELSE
      INDEX2 := 1; 
      WHILE (INDEX <= STOP AND INDEX2>0) DO
	    C := BUF[INDEX];
        IF C=BYTE#60 THEN    
		  INDEX2 := INDEX2+1;     
        ELSIF C=BYTE#62 THEN 
		  INDEX2 := INDEX2-1;     
        ELSIF C=BYTE#34 OR C=BYTE#39 THEN 
          INDEX := INDEX + 1;
          WHILE (INDEX <= STOP) DO
   	        C := BUF[INDEX];
            IF C=BYTE#34 OR C=BYTE#39 THEN 
              EXIT;
			END_IF;       
            INDEX := INDEX + 1;
          END_WHILE;
		END_IF;       
        INDEX := INDEX + 1;
      END_WHILE;
      CTRL.BLOCK1_STOP := INT_TO_UINT(INDEX-2);
    END_IF;
    BUFFER_TO_STRING(size:=INT_TO_UINT(STOP+1),start:=CTRL.BLOCK1_START,stop:=CTRL.BLOCK1_STOP,pt:=BUF);
    CTRL.VALUE:=BUFFER_TO_STRING.BUFFER_TO_STRING;
    BUF:=BUFFER_TO_STRING.pt;
    CTRL.COUNT := CTRL.COUNT + UINT#1;
    MODE := 100; 
	IF BIT_OF_DWORD(WORD_TO_DWORD(COMMAND),CTRL.TYP) THEN
      RETURN;
    END_IF;
  END_CASE;
END_WHILE;
END_FUNCTION_BLOCK

CASE state OF
00:
  IF ACTIVATE AND NOT last_state THEN
    state := 20;
	DONE := FALSE;
	BUSY := TRUE;
	ERROR_C := DWORD#0;
	ERROR_T := BYTE#0;
  END_IF;
20: 
  STRING_TO_URL.STR:='http:
  STRING_TO_URL.DEFAULT_PROTOCOL:='';
  STRING_TO_URL.DEFAULT_PATH:='';
  STRING_TO_URL();
  URL_DATA:=STRING_TO_URL.STRING_TO_URL;
  URL_DATA.QUERY := CONCAT('w=',LOCATION);
  IF UNITS THEN
    URL_DATA.QUERY := CONCAT(URL_DATA.QUERY,'&u=f'); 
  ELSE
    URL_DATA.QUERY := CONCAT(URL_DATA.QUERY,'&u=c'); 
  END_IF;
  state := 40;
40:
  IF DNS_CLIENT.DONE THEN
    state := 60;
  ELSIF (DNS_CLIENT.ERROR > DWORD#00) THEN
    ERROR_C := DNS_CLIENT.ERROR;
	ERROR_T := BYTE#01;
    state   := 100;
  END_IF;
60:
  IF HTTP_GET.DONE THEN
    state := 80;
    CTRL.START_POS := HTTP_GET.BODY_START;
    CTRL.STOP_POS  := HTTP_GET.BODY_STOP;
    CTRL.COMMAND   := WORD#2#10000000_00011000; 
	CTRL.WATCHDOG  := T#1ms;
  ELSIF (HTTP_GET.ERROR > DWORD#00) THEN
    ERROR_C := HTTP_GET.ERROR;
	  ERROR_T := BYTE#02;
    state   := 100;
  END_IF;
80:
  XML_READER.CTRL := CTRL;
  XML_READER.BUF  := R_BUF.BUFFER;
  XML_READER();
  CTRL         := XML_READER.CTRL;
  R_BUF.BUFFER := XML_READER.BUF;
  IF CTRL.TYP < 98 THEN 
    value_int := 0;
	value_real := 0.0;
