tx := UDINT_TO_TIME(T_PLC_MS.T_PLC_MS);
IF TEST THEN
	status := BYTE#103;
	start := tx;
	ARX := TRUE;
END_IF;
CASE _BYTE_TO_INT(status) OF
	0:	
		IF ARE AND NOT ARX THEN
			status := BYTE#103;
			start := tx;
			ARX := TRUE;
		END_IF;
	100:	
		IF T_DIAG > T#0s AND tx > next_diag AND ARE AND NOT ARX THEN
				status := BYTE#103;
				start := tx;
				ARX := TRUE;
		ELSIF T_CAL > T#0s AND tx > next_cal AND ARE AND NOT ARX THEN
			IF pos > BYTE#127 THEN
				OUT1 := TRUE;
				OUT2 := FALSE;
				ramp.IN := BYTE#255;
				ARX := TRUE;
			ELSE
				OUT1 := FALSE;
				OUT2 := TRUE;
				ramp.IN := BYTE#0;
				ARX := TRUE;
			END_IF;
			status := BYTE#101;
			start := tx;
		ELSE
			IF NOT(OUT1 OR OUT2) THEN next_cal := next_cal + (tx-last); END_IF;
			ramp.IN := IN;
		END_IF;
	101:	
		IF tx - start < T_EXT THEN
			next_cal := tx + T_CAL;
		ELSIF SWITCH_AVAIL AND END_POS THEN
			STATUS := BYTE#100;
			ARX := FALSE;
		ELSIF tx - start > T_EXT + T_RUN THEN
			ERROR := SWITCH_AVAIL;
			ARX := FALSE;
		END_IF;
	103:	
		IF tx - start < T_EXT THEN
			ERROR := FALSE;
			ramp.TR := T_RUN;
			ramp.TF := T_RUN;
			OUT1 := TRUE;
			OUT2 := FALSE;
			ramp.IN := BYTE#255;
		ELSIF SWITCH_AVAIL AND END_POS THEN
			ramp.TR := tx - start;
			STATUS := BYTE#104;
		ELSIF tx - start > T_EXT + T_RUN THEN
			ERROR := SWITCH_AVAIL;
			STATUS := BYTE#104;
			start := tx;
		END_IF;
	104:	
		IF tx - start < T_ext THEN
			OUT1 := FALSE;
			OUT2 := TRUE;
			ramp.IN := BYTE#0;
			next_diag := tx + T_DIAG;
		ELSIF SWITCH_AVAIL AND END_POS THEN
			ramp.TR := tx - start;
			IF DINT_TO_TIME(ABS(TIME_TO_DINT(ramp.TR) - TIME_TO_DINT(ramp.TF)) * DINT#10) > T_RUN THEN error := TRUE; END_IF;
			STATUS := BYTE#100;
			ARX := FALSE;
			next_cal := tx + T_CAL;
		ELSIF tx - start > T_EXT + T_RUN THEN
			IF SWITCH_AVAIL THEN ERROR := TRUE; END_IF;
			STATUS := BYTE#100;
			ARX := FALSE;
			next_CAL := tx + T_CAL;
		END_IF;
END_CASE;
ramp(OUT := POS);
POS := ramp.OUT;
IF STATUS = BYTE#100 THEN
	OUT1 := ramp.UP;
	OUT2 := ramp.DN;
END_IF;
IF SWITCH_AVAIL AND END_POS THEN
	POS := SEL_BYTE(POS > BYTE#127, BYTE#0, BYTE#255);
	next_cal := tx + T_CAL;
END_IF;
last := tx;
END_FUNCTION_BLOCK

