		pre_heat := FALSE;
		IF over_temp THEN
			status := BYTE#9;
			fail := TRUE;
		END_IF;
		last_change := tx;
		last := tx;
		state := 1;
	END_IF;
END_IF;
IF rst_timer THEN
	runtime1 := UDINT#0;
	runtime2 := UDINT#0;
	cycles := UDINT#0;
	cycles2 := UDINT#0;
END_IF;
IF (status > BYTE#0 AND status < BYTE#100) OR rst THEN RETURN; END_IF;
CASE state OF
1:	
	IF in AND flame THEN
		state := 7;
		pre_heat := FALSE;
		status := BYTE#2;
		last_change := tx;
	ELSIF in THEN
		pre_heat := TRUE;
		state := 2;
		last_change := tx;
	END_IF;
2:	
	IF (tx- last_change >= pre_heat_time AND oil_temp) OR (oil_temp AND NOT oil_temp_last) THEN
		motor := TRUE;
		state := 3;
		last_change := tx;
	ELSIF tx - last_change >= pre_heat_time AND NOT oil_temp THEN
		state := 7;
		pre_heat := FALSE;
		status := BYTE#1;
		last_change := tx;
	ELSIF flame THEN
		state := 7;
		pre_heat := FALSE;
		status := BYTE#2;
		last_change := tx;
	END_IF;
3:	
	IF tx - last_change >= pre_vent_time - pre_ignite_time THEN
		ignite := TRUE;
		state := 4;
		last_change := tx;
	ELSIF flame THEN
		state := 7;
		pre_heat := FALSE;
		motor := FALSE;
		status := BYTE#3;
		last_change := tx;
	END_IF;
4:	
	IF tx - last_change >= pre_ignite_time THEN
		coil1 := TRUE;
		state := 5;
		last_change := tx;
	END_IF;
5:	
	IF tx - last_change >= safety_time OR flame THEN
		IF NOT flame THEN
			state := 7;
			motor := FALSE;
			coil1 := FALSE;
			pre_heat := FALSE;
			ignite := FALSE;
			status := BYTE#4;
			last_change := tx;
		ELSE
			state := 6;
			last_change := tx;
		END_IF;
	END_IF;
6:	
	IF NOT flame AND NOT multiple_ignition THEN
		state := 7;
		motor := FALSE;
		coil1 := FALSE;
		coil2 := FALSE;
		pre_heat := FALSE;
		ignite := FALSE;
		status := BYTE#5;
		last_change := tx;
	ELSIF NOT flame AND multiple_ignition THEN
		ignite := TRUE;
		state := 5;
		coil2 := FALSE;
		last_change := tx;
	ELSE
		IF tx - last_change >= post_ignite_time THEN
			ignite := FALSE;
		END_IF;
		IF tx - last_change >= stage2_delay AND stage2 THEN
			coil2 := TRUE;
		ELSE
			coil2 := FALSE;
		END_IF;
	END_IF;
END_CASE;
IF NOT in THEN
	state := 1;
	motor := FALSE;
	coil1 := FALSE;
	coil2 := FALSE;
	ignite := FALSE;
	pre_heat := FALSE;
	last_change := tx;
END_IF;
timer1(in := flame AND in AND motor AND coil1 AND NOT coil2, SECONDS := runtime1, CYCLES := cycles);
cycles := timer1.CYCLES;
runtime1 := timer1.SECONDS;
timer2(in := flame AND in AND motor AND coil1 AND coil2, SECONDS := runtime2, CYCLES := cycles2);
cycles2 := timer2.CYCLES;
runtime2 := timer2.SECONDS;
KWH := UDINT_TO_REAL(runtime1) * KW1 / 3600.0 + UDINT_TO_REAL(runtime2) * KW2 / 3600.0;
last := tx;
IF status > BYTE#0 AND status < BYTE#100 THEN
	fail := TRUE;
ELSE
	fail := FALSE;
	IF NOT in THEN
		status := BYTE#110;
	ELSIF flame AND in AND motor AND coil2 AND coil1 THEN
		status := BYTE#113;
	ELSIF flame AND in AND motor AND coil1 THEN
		status := BYTE#112;
	ELSE
		status := BYTE#111;
	END_IF;
END_IF;
END_FUNCTION_BLOCK

