	enabled := DAY_OF_MONTH(dat) = 1;
26:	
	enabled := day_of_month(dat + TIME_TO_UDINT(t#1d)) = 1;
27:	
	enabled := DAY_OF_MONTH(dat) = 31 AND MONTH_OF_DATE(dat) = 12;
28:	
	enabled := DAY_OF_YEAR(dat) = 1;
ELSE
	enabled := FALSE;
END_CASE;
IF enabled AND NOT Q AND daytime >= start AND run_date <> dat THEN
	Q := TRUE;
	activation := tx;
	run_date := dat;
ELSIF Q AND tx - activation >= duration THEN
	Q := FALSE;
END_IF;
last_check := Tx;
END_FUNCTION_BLOCK

stop := LEN(event);
IF (GET_CHAR(event,1) <> 60) AND (GET_CHAR(event,stop) <> 62) THEN RETURN; END_IF;
start := 2;
step := 0;
FOR pos := 2 TO stop DO
    char := GET_CHAR(event,pos);
	IF char = 59 OR char = 62 THEN
		tmp := MID(event, pos - start, start);
		CASE step OF
			0:	
                FSTRING_TO_BYTE(IN:=tmp);
                TIMER_EVENT_DECODE.typ := FSTRING_TO_BYTE.FSTRING_TO_BYTE;
			1:	
                FSTRING_TO_BYTE(IN:=tmp);
                TIMER_EVENT_DECODE.channel := FSTRING_TO_BYTE.FSTRING_TO_BYTE;
			2:	
                IS_CC(str:=tmp,cmp:='0123456789abcdefABCDEF#');
				IF IS_CC.IS_CC THEN
                    FSTRING_TO_BYTE(IN:=tmp);
                    TIMER_EVENT_DECODE.DAY := FSTRING_TO_BYTE.FSTRING_TO_BYTE;
				ELSIF TIMER_EVENT_DECODE.typ = BYTE#2 THEN
                    FSTRING_TO_WEEK(WEEK:=tmp,LANG:=LANG);
                    TIMER_EVENT_DECODE.DAY := FSTRING_TO_WEEK.FSTRING_TO_WEEK;
				ELSE
                    FSTRING_TO_WEEKDAY(WDAY:=tmp,LANG:=LANG);
                    TIMER_EVENT_DECODE.DAY := INT_TO_BYTE(FSTRING_TO_WEEKDAY.FSTRING_TO_WEEKDAY);
				END_IF;
			3:	
			    STRING_TO_TOD(_TOD:=tmp);
                TIMER_EVENT_DECODE.start := STRING_TO_TOD.STRING_TO_TOD;
			4:	
                _STRING_TO_TIME(_TIME:=tmp);
                TIMER_EVENT_DECODE.duration := _STRING_TO_TIME.STRING_TO_TIME;
			5:	
                FSTRING_TO_BYTE(IN:=tmp);
				TIMER_EVENT_DECODE.land := FSTRING_TO_BYTE.FSTRING_TO_BYTE;
			6:	
                FSTRING_TO_BYTE(IN:=tmp);
				TIMER_EVENT_DECODE.LOR := FSTRING_TO_BYTE.FSTRING_TO_BYTE;
		END_CASE;
		start := pos + 1;
		step := step + 1;
	END_IF;
END_FOR;
END_FUNCTION_BLOCK

SUN_RISE := SUN_RISE / UDINT#1000 * UDINT#1000;
SUN_SET := SUN_SET / UDINT#1000 * UDINT#1000;
T_PLC_MS();
tx:= T_PLC_MS.T_PLC_MS;
IF NOT init THEN
	init := TRUE;
	tl := tx;
END_IF;
tc := UDINT_TO_TIME(tx - tl);
IF tc < t#200ms THEN RETURN; END_IF;
tl := tx;
deb(in := SWITCH, TD := T_DEBOUNCE, PM := TRUE);
tdx := DT_TO_TOD(dt_in);
wdx := DAY_OF_WEEK(DT_TO_DATE(dt_in));
IF deb.Q THEN
	qx := NOT qx;
	status := BYTE#110;
ELSIF holiday AND NOT enable_holiday THEN
	qx := FALSE;
ELSIF wdx = 6 AND NOT enable_saturday THEN
	qx := FALSE;
ELSIF wdx = 7 AND NOT enable_sunday THEN
	qx := FALSE;
ELSIF T_day_start > UDINT#00  AND tdx - T_DAY_START <= TIME_TO_UDINT(tc) THEN
	qx := TRUE;
	status := BYTE#111;
ELSIF T_DAY_STOP > UDINT#00  AND tdx - T_DAY_STOP <= TIME_TO_UDINT(tc) THEN
	qx := FALSE;
	status := BYTE#112;
ELSIF T_RISE_START > T#0s AND tdx - SUN_RISE + TIME_TO_UDINT(T_RISE_START) <= TIME_TO_UDINT(tc) THEN
	qx := TRUE;
	status := BYTE#113;
ELSIF T_RISE_STOP > T#0s AND tdx - SUN_RISE - TIME_TO_UDINT(T_RISE_STOP) <= TIME_TO_UDINT(tc) THEN
	qx := FALSE;
	status := BYTE#114;
ELSIF T_SET_start > T#0s AND tdx - SUN_SET + TIME_TO_UDINT(T_SET_START) <= TIME_TO_UDINT(tc) THEN
	qx := TRUE;
	status := BYTE#115;
ELSIF T_SET_STOP > T#0s AND tdx - SUN_SET - TIME_TO_UDINT(T_SET_STOP) <= TIME_TO_UDINT(tc) THEN
	qx := FALSE;
	status := BYTE#116;
END_IF;
mx(in := qx, ena := ENA, on := ON, off := OFF, man := MAN);
Q := mx.Q;
IF mx.STATUS > BYTE#100 THEN status := mx.STATUS; END_IF;
END_FUNCTION_BLOCK

IF RST THEN
	last_execute := UDINT#00; 
	FOR pos := 0 TO ARRAY_MAX DO
		IF (PROG[pos].CHANNEL >= OFS) AND (_BYTE_TO_INT(PROG[pos].CHANNEL) < (_BYTE_TO_INT(OFS) + 4)) THEN PROG[pos].LAST := last_execute; END_IF;
	END_FOR;
	FOR pos := 0 TO channel_max DO
		qs[pos] := FALSE;
	END_FOR;
ELSIF dtime <> last_execute THEN
	last_execute := DTIME;
	day_start := DATE_TO_DT(DT_TO_DATE(DTIME));
	FOR pos := 0 TO channel_max DO qn[pos] := FALSE; END_FOR;
	FOR pos := 0 TO ARRAY_MAX DO
		event := prog[pos];
		channel := _BYTE_TO_INT(event.CHANNEL) - _BYTE_TO_INT(OFS);
		IF (event.TYP > BYTE#0) AND (channel >= 0) AND (channel <= channel_max) THEN
			ma[channel] := event.LAND;
			mo[channel] := event.LOR;
			CASE _BYTE_TO_INT(event.TYP) OF
				1:	
					start := day_start + event.start;
					qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
				2: 	
					IF (SHR(BYTE#128, DAY_OF_WEEK(DT_TO_DATE(Dtime))) AND event.DAY) > BYTE#0 THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				3:	
					IF current_day MOD _BYTE_TO_DINT(event.DAY) = DINT#0 THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				10:	
					IF DAY_OF_WEEK(DT_TO_DATE(DTIME)) = BYTE_TO_INT(event.DAY) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				20:	
					IF DAY_OF_MONTH(DT_TO_DATE(DTIME)) = BYTE_TO_INT(event.DAY) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				21:	
					IF DT_TO_DATE(DTIME) = MONTH_END(DT_TO_DATE(dtime)) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				30:	
					IF DAY_OF_YEAR(DT_TO_DATE(DTIME)) = BYTE_TO_INT(event.DAY) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				31:	
					IF DT_TO_DATE(DTIME) = YEAR_END(YEAR_OF_DATE(DT_TO_DATE(dtime))) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				40:	
					IF LEAP_DAY(DT_TO_DATE(dtime)) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				41: 
					IF HOLY THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				42: 
					IF (Holy OR (DAY_OF_WEEK(DT_TO_DATE(dtime)) = 6) OR (DAY_OF_WEEK(DT_TO_DATE(dtime)) = 7)) THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				43:	
					IF DAY_OF_WEEK(DT_TO_DATE(dtime)) < 6 THEN
						start := day_start + event.start;
						qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
					END_IF;
				50: 
					CASE _BYTE_TO_INT(prog[pos].DAY) OF
						0:	tx := tref_0;
						1:	tx := tref_1;
					ELSE
						tx := UDINT#0 ;
					END_CASE;
					start := day_start + tx + event.start;
					qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
				51:	
					CASE _BYTE_TO_INT(prog[pos].DAY) OF
						0:	tx := tref_0;
						1:	tx := tref_1;
					ELSE
						tx := UDINT#0 ;
					END_CASE;
					start := day_start + tx - event.start;
					qn[channel] := dtime >= start AND dtime <= start + TIME_TO_UDINT(event.DURATION);
				52 : 
					CASE _BYTE_TO_INT(prog[pos].DAY) OF
						0:	tx := tref_0;
						1:	tx := tref_1;
					ELSE
						tx := UDINT#0 ;
					END_CASE;
					start := day_start + tx + event.start;
					IF dtime >= start AND day_start > event.LAST THEN
						qs[channel] := TRUE;
						prog[pos].LAST := day_start;
					END_IF;
				53 : 
					CASE _BYTE_TO_INT(prog[pos].DAY) OF
						0:	tx := tref_0;
						1:	tx := tref_1;
					ELSE
						tx := UDINT#0 ;
					END_CASE;
					start := day_start + tx + event.start;
					IF dtime >= start AND day_start > event.LAST THEN
						qs[channel] := FALSE;
						prog[pos].LAST := day_start;
					END_IF;
				54 : 
					CASE _BYTE_TO_INT(prog[pos].DAY) OF
						0:	tx := tref_0;
						1:	tx := tref_1;
					ELSE
						tx := UDINT#0 ;
					END_CASE;
					start := day_start + tx - event.start;
					IF dtime >= start AND day_start > event.LAST THEN
						qs[channel] := TRUE;
						prog[pos].LAST := day_start;
					END_IF;
				55 : 
					CASE _BYTE_TO_INT(prog[pos].DAY) OF
						0:	tx := tref_0;
						1:	tx := tref_1;
					ELSE
						tx := UDINT#0 ;
					END_CASE;
					start := day_start + tx - event.start;
					IF dtime >= start AND day_start > event.LAST THEN
						qs[channel] := FALSE;
						prog[pos].LAST := day_start;
					END_IF;
			END_CASE;
		END_IF;
	END_FOR;
END_IF;
mask := BYTE#255;
mask:=BIT_LOAD_B(mask,L0,0);
mask:=BIT_LOAD_B(mask,L1,1);
mask:=BIT_LOAD_B(mask,L2,2);
mask:=BIT_LOAD_B(mask,L3,3);
Q0 := ENQ AND ((qn[0] OR qs[0]) AND ((ma[0] AND mask) = ma[0]) OR ((mo[0] AND mask) > BYTE#0) OR (man AND BIT_OF_DWORD(BYTE_TO_DWORD(MI),0)));
Q1 := ENQ AND ((qn[1] OR qs[1]) AND ((ma[1] AND mask) = ma[1]) OR ((mo[1] AND mask) > BYTE#1) OR (man AND BIT_OF_DWORD(BYTE_TO_DWORD(MI),1)));
Q2 := ENQ AND ((qn[2] OR qs[2]) AND ((ma[2] AND mask) = ma[2]) OR ((mo[2] AND mask) > BYTE#2) OR (man AND BIT_OF_DWORD(BYTE_TO_DWORD(MI),2)));
Q3 := ENQ AND ((qn[3] OR qs[3]) AND ((ma[3] AND mask) = ma[3]) OR ((mo[3] AND mask) > BYTE#3) OR (man AND BIT_OF_DWORD(BYTE_TO_DWORD(MI),3)));
IF NOT enq THEN
	status := BYTE#100;
ELSIF man THEN
	status := BYTE#101;
ELSE
	status := BYTE#102;
END_IF;
END_FUNCTION_BLOCK

ft1(X := TS, T := T_FILTER);
IF rst OR NOT init THEN
	init := TRUE;
	IF T24 = -1000.0 THEN t24 := INT_TO_REAL(ft1.Y) * 0.1; END_IF;
	FOR pos := 0 TO 47 DO
		samples[pos] := REAL_TO_INT(T24 * 10.0);
	END_FOR;
	pos := 0;
	sum := INT_TO_DINT(samples[0]) * DINT#48;
	TA := (INT_TO_REAL(ft1.Y) * 0.1 + OFS) * SCALE;
	T24 := (DINT_TO_REAL(sum) * 0.00208333333333 + OFS) * SCALE;
	tp := TRUE;
ELSIF (dti / UDINT#60 MOD UDINT#30) = UDINT#0 AND DTI > last THEN
	last := DTI + TIME_TO_UDINT(T#1m);
	sum := sum - INT_TO_DINT(samples[pos]);
	samples[pos] := ft1.Y;
	sum := sum + INT_TO_DINT(samples[pos]);
	pos := INC1(pos, 48);
	TA := (INT_TO_REAL(ft1.Y) * 0.1 + OFS) * SCALE;
	T24 := (DINT_TO_REAL(sum) * 0.00208333333333 + OFS) * SCALE;
	tmp_max := -32000;
	tmp_min := 32000;
	FOR i := 0 TO 47 DO
		tmp_max := MAX(tmp_max, samples[i]);
		tmp_min := MIN(tmp_min, samples[i]);
	END_FOR;
	T24_MAX := (INT_TO_REAL(tmp_max) * 0.1 + OFS) * SCALE;
	T24_MIN := (INT_TO_REAL(tmp_min) * 0.1 + OFS) * SCALE;
	tp := TRUE;
ELSE
	tp := FALSE;
END_IF;
END_FUNCTION_BLOCK

